import { GENERATION_DEFAULTS, DEFAULT_SYSTEM_PROMPT } from '../shared/types';
import { DEFAULT_PROMPTS } from '../shared/prompts';
import {test,expect,type Page} from '@playwright/test';
const raw={spec:'chara_card_v2',spec_version:'2.0',data:{name:'岚',description:'港城旅店的主人。她守着一盏长明的灯，等待远行的旅人。',personality:'冷静、敏锐，善于倾听。',scenario:'雨夜，北方港城的一间旅店。',first_mes:'门外传来脚步声。岚放下手中的书，望向你。\n「雨很大，进来坐坐吧。」',mes_example:'',system_prompt:'',post_history_instructions:'',alternate_greetings:['清晨，窗外的海风带来潮声。'],tags:['奇幻','旅店'],creator:'测试作者',extensions:{}}};
const character={id:'c1',name:'岚',description:raw.data.description,creator:'测试作者',tags:['奇幻','旅店'],format:'V2',hasAvatar:false,source:'',sourceUrl:'',unsupported:[],card:raw};
const settings={userName:'旅人',persona:'一位从北方归来的旅人。',systemPrompt:'保持角色与故事连贯。',...GENERATION_DEFAULTS};
const book={id:'b1',name:'北境港城',enabled:true,count:2,raw:{name:'北境港城',entries:[{keys:['港城'],content:'港城的灯塔每晚亮起。',enabled:true},{keys:[],content:'故事发生在初秋。',constant:true,enabled:true}]},unsupported:[]};
const session={id:'s1',title:'港城的雨夜',characterName:'岚',updatedAt:1790990000000,settings,bookIds:['b1'],character:raw,generationId:null as string|null};
const greeting={id:'m1',role:'assistant',content:raw.data.first_mes,status:'completed',ordinal:0,requestId:null,createdAt:1790990000000};
async function fixture(page:Page,{empty=false,fail=false,delay=false,streamDelay=false,stopDelay=false,partial=false,long=false,promptAdmin=true,agent=false}={}) {
 let promptTexts={...DEFAULT_PROMPTS};let activities:Record<string,unknown>[]=[];let estimatedTokens=8250,coveredMessages=0;
 const current=structuredClone(session);
 const cards=empty?[]:[structuredClone(character)],books=empty?[]:[structuredClone(book)],sessions=empty?[]:[structuredClone(current)];let messages:Record<string,unknown>[]=empty?[]:[structuredClone(greeting)];let pending='';let generationCount=0;let savedSettings=structuredClone(settings);if(long)messages=[{...greeting,content:Array.from({length:18},(_,i)=>`第${i+1}段。雨点敲着旅店的窗，岚整理好桌边的书，等待你的回答。`).join('\n\n')}];
 await page.route('**/api/**',async route=>{
  const req=route.request(),url=new URL(req.url()),p=url.pathname,method=req.method();if(delay)return;
  if(fail){await route.fulfill({status:503,json:{message:'服务暂时不可用'}});return;}
  const multipart=req.headers()['content-type']?.includes('multipart/form-data')?await new Response(Uint8Array.from(req.postDataBuffer()!),{headers:{'Content-Type':req.headers()['content-type']}}).formData():null;
  const body=multipart?{card:JSON.parse(String(multipart.get('card')))}:req.headers()['content-type']?.includes('application/json')?req.postDataJSON()??{}:{};let data:unknown={ok:true};
  if(p==='/api/models')data={models:[{id:'rp',name:'RP 动态路由',available:true,contextTokens:16384,parameters:{topK:true,penalties:true,thinking:true,topKMax:1000}}]};
  else if(p==='/api/prompts'){if(method==='PUT')promptTexts=body.texts;data={revision:'fixture',texts:promptTexts,admin:promptAdmin};}
  else if(p==='/api/settings'){if(method==='PUT')savedSettings=body;data=savedSettings;}
  else if(p==='/api/messaging/telegram')data={configured:true,botUsername:'saki_main_bot',routes:[]};
  else if(p==='/api/characters'&&method==='GET')data={characters:cards};
  else if(p==='/api/characters'&&method==='POST'){const uploaded=multipart?body.card:req.headers()['x-filename']?raw:req.postDataJSON();expect(uploaded).not.toBeNull();cards.push({...character,id:'c2',name:uploaded.data.name,description:uploaded.data.description,card:uploaded,hasAvatar:!!(multipart?.get('avatar')||multipart?.get('avatarImageId'))});data=cards.at(-1);}
  else if(p==='/api/characters/c1'&&method==='PATCH'){Object.assign(cards[0],{card:body.card,name:body.card.data.name,hasAvatar:!!(multipart?.get('avatar')||multipart?.get('avatarImageId'))||cards[0].hasAvatar});data=cards[0];}
  else if(p==='/api/characters/c1'&&method==='DELETE')cards.splice(0,1);
  else if(p==='/api/characters/c1')data=cards[0];
  else if(p==='/api/discover')data={total:13,sort:url.searchParams.get('sort'),source:url.searchParams.get('source'),page:Number(url.searchParams.get('page')),hasMore:Number(url.searchParams.get('page'))===1,results:url.searchParams.get('q')==='无结果'?[]:[{id:'source1',name:'伊莲',description:'一位守护山间书库的学者。',creator:'G-reen',tags:['奇幻'],popularity:1240,createdAt:'2026-10-01T00:00:00Z',source:url.searchParams.get('source'),sourceUrl:'https://chub.ai/characters/test/role'}]};
  else if(p==='/api/install'){cards.push({...character,id:'installed',name:'伊莲'});data=cards.at(-1);}
  else if(p==='/api/worldbooks'&&method==='GET')data={worldbooks:books};
  else if(p==='/api/worldbooks'&&method==='POST'){books.push({...book,id:'b2'});data=books.at(-1);}
  else if(p==='/api/worldbooks/b1'&&method==='PATCH'){Object.assign(books[0],body);data=books[0];}
  else if(p==='/api/worldbooks/b1'&&method==='DELETE')books.splice(0,1);
  else if(p==='/api/sessions'&&method==='GET')data={sessions};
  else if(p==='/api/sessions'&&method==='POST'){data=current;sessions.splice(0,sessions.length,current);messages=[greeting];}
  else if(p==='/api/sessions/s1/generate'){
   pending='pending-'+(++generationCount);current.generationId=pending;const interrupted=partial&&generationCount===1;
   if(body.regenerate){const target=messages.find(m=>m.id===body.messageId)??messages.at(-1)!;messages=messages.filter(m=>Number(m.ordinal)<Number(target.ordinal)||(target.role==='user'&&m.id===target.id));activities=activities.filter(a=>Number(a.ordinal)<Number(target.ordinal));}
   const ordinal=Number(messages.at(-1)?.ordinal??-1)+1;
   if(!body.regenerate)messages.push({id:'user-'+generationCount,role:'user',content:body.content,status:'completed',ordinal,requestId:body.requestId,createdAt:1790990000001});
   const generated={id:pending,role:'assistant',content:(interrupted?'岚轻轻抬起头，':'岚把热茶放在桌上。\n「你从哪里来？」'),candidates:interrupted?[]:['我接过热茶，问她港城今晚有什么消息。','我走到窗边，看看雨中的港口。','我放下行囊，询问有没有安静的房间。'],status:interrupted?'error':'completed',finishReason:interrupted?'length':'stop',ordinal:body.regenerate?ordinal:ordinal+1,requestId:body.requestId,createdAt:1790990000002};messages.push(generated);
   const records:Record<string,unknown>[]=[{id:pending+':body',messageId:pending,ordinal:generated.ordinal,kind:'body',title:'对话生成',status:'completed',result:{characters:generated.content.length},createdAt:1790990000001},{id:pending+':director',messageId:pending,ordinal:generated.ordinal,kind:'director',title:'Director · 下一步',status:'completed',result:{candidates:generated.candidates},createdAt:1790990000002}];
   if(agent)records.splice(1,0,{id:pending+':tool',messageId:pending,ordinal:generated.ordinal,kind:'tool',title:'search_memory',status:'completed',input:{query:'港城'},result:[{text:'灯塔每晚亮起。',source:{bookId:'b1'}}],createdAt:1790990000001},{id:pending+':compression',messageId:pending,ordinal:generated.ordinal,kind:'compression',title:'压缩上下文',status:'completed',result:{summary:{text:'旅人来到雨夜的港城旅店。',covered:['m1']}},createdAt:1790990000001});activities.push(...records);
   const frames=[{type:'start',messageId:pending,requestId:body.requestId},{type:'delta',text:generated.content},...records.map(activity=>({type:'activity',activity}))];
   if(streamDelay){messages[messages.length-1]={...generated,status:'pending'};await route.fulfill({contentType:'text/event-stream',body:frames.map(e=>'data: '+JSON.stringify(e)+'\n\n').join('')});return;}
   current.generationId=null;if(interrupted)frames.push({type:'error',message:'回复达到长度上限，内容已保存'} as never);frames.push({type:'done',message:generated} as never);await route.fulfill({contentType:'text/event-stream',body:frames.map(e=>'data: '+JSON.stringify(e)+'\n\n').join('')});return;
  }
  else if(p==='/api/sessions/s1/stop'){messages=messages.map(m=>m.id===pending?{...m,status:'aborted',finishReason:'stopped'}:m);if(stopDelay)setTimeout(()=>current.generationId=null,1700);else current.generationId=null;}
  else if(p==='/api/sessions/s1/messages'){const target=messages.find(m=>m.id===body.messageId)!;messages=messages.filter(m=>Number(m.ordinal)<Number(target.ordinal)||(method==='PATCH'&&m.id===target.id));if(method==='PATCH')Object.assign(target,{content:body.content,candidates:[]});activities=activities.filter(a=>Number(a.ordinal)<Number(target.ordinal));}
  else if(p==='/api/sessions/s1/command'){const compress=body.content==='/compress';if(compress){estimatedTokens=4200;coveredMessages=3;}activities.push({id:body.requestId,messageId:null,ordinal:messages.at(-1)?.ordinal??-1,kind:compress?'compression':'status',title:compress?'压缩上下文':'当前状态',status:'completed',result:compress?{summary:{text:'旅人与岚在旅店交谈。',covered:['m1']}}:{state:{scene:'港城旅店'},context:{estimatedTokens,contextTokens:32768}},createdAt:1790990000003});}
  else if(p==='/api/sessions/s1'&&method==='PATCH'){Object.assign(current,body);data=current;}
  else if(p==='/api/sessions/s1'&&method==='DELETE')sessions.splice(0,sessions.length);
  else if(p==='/api/sessions/s1')data={session:current,messages:[...new Map(messages.map(m=>[m.ordinal,m] as const)).values()],activities,context:{estimatedTokens,contextTokens:32768,inputRatio:1.2,summaryTokens:coveredMessages?200:0,coveredMessages,includedMessages:messages.length}};
  else if(p.endsWith('/export')){await route.fulfill({contentType:'application/json',body:JSON.stringify(raw)});return;}
  await route.fulfill({json:data});
 });
 await page.goto('/e2e/index.html');
}
async function nav(page:Page,name:string){await page.getByRole('navigation').getByRole('link',{name,exact:true}).click();}
async function shot(page:Page,name:string,keepFocus=false){const dialog=page.getByRole('dialog');if(await dialog.isVisible()){await expect.poll(()=>dialog.evaluate(el=>el.contains(document.activeElement))).toBe(true);await dialog.focus();await expect(dialog).toBeFocused();}await page.mouse.move(0,0);if(!keepFocus)await page.evaluate(()=>{if(document.activeElement instanceof HTMLElement)document.activeElement.blur();});await expect(page).toHaveScreenshot(name,{fullPage:true});expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);}
